// Small deterministic RNG (mulberry32) so a screenshot seed replays the same game.
export function makeRng(seed) {
  let a = seed >>> 0;
  return function rng() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function shuffledDeck(rng) {
  const deck = CARD_DEFS.map((d) => d.id);
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return deck;
}

let uidCounter = 0;
export function makeCard(defId) {
  const def = defById(defId);
  uidCounter += 1;
  return {
    uid: 'c' + uidCounter + '-' + defId,
    defId: def.id,
    name: def.name,
    faction: def.faction,
    type: def.type,
    cost: def.cost,
    atk: def.atk ?? 0,
    hp: def.hp ?? 0,
    maxHp: def.hp ?? 0,
    text: def.text,
    effect: def.effect ?? null,
    sick: false,
    canAttack: false,
    justPlayed: false,
  };
}
